use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let left = input.as_array().unwrap();
    let right = input.as_array().unwrap();
    let mut common_keys = Vec::new();
    let mut left_values = Vec::new();
    let mut right_values = Vec::new();

    for (left_key, left_value) in left.iter() {
        for (right_key, right_value) in right.iter() {
            if left_key == right_key {
                common_keys.push(left_key.clone());
                left_values.push(left_value.clone());
                right_values.push(right_value.clone());
            }
        }
    }

    let mut result = Value::Array::new();
    for key in common_keys {
        result.push(Value::String(key));
        result.push(Value::Number(serde_json::Number::from(left_values.iter().find(|&x| x == &key).unwrap())));
        result.push(Value::Number(serde_json::Number::from(right_values.iter().find(|&x| x == &key).unwrap())));
    }

    result
}
